#!/bin/bash
# Test-owned git process instrumentation. The verified core.hooksPath pin and
# every other argument are forwarded unchanged to real git. Project hooks do
# not supply these barriers: this executable explicitly invokes test callbacks
# to observe the lock around git operations. No production bypass is provided.
# trace:BUG-1929 | ai:codex
args=("$@")
command_name=""
for ((i=0; i<${#args[@]}; i++)); do
    case "${args[$i]}" in
        -c|-C|--git-dir|--work-tree) i=$((i+1));;
        -*) ;;
        *) command_name="${args[$i]}"; break;;
    esac
done
callback() {
    local name="$1"
    shift
    local hook="$T1717_CALLBACKS/$name"
    [ -x "$hook" ] || return 0
    # The real git already runs shipped hooks. These callbacks only add test
    # barriers / injected failures; running a shipped post-commit twice would
    # turn a healthy sentinel into a false bypass observation.
    if grep -qE '^# (AIDA .*hook|Generated by AIDA scaffolding)' "$hook"; then
        return 0
    fi
    "$hook" "$@"
}
case "$command_name" in
    commit) callback pre-commit || exit $?;;
    push)
        sha=$("$T1717_REAL_GIT" rev-parse HEAD) || exit $?
        printf 'refs/heads/aida-store %s refs/heads/aida-store %040d\n' "$sha" 0 | callback pre-push || exit $?;;
    rebase)
        case " $* " in *' --abort '*) callback reference-transaction prepared || exit $?;; esac;;
    gc) callback pre-auto-gc || exit $?;;
esac
"$T1717_REAL_GIT" "$@"
result=$?
if [ "$result" = 0 ]; then
    case "$command_name" in
        commit) callback post-commit;;
        rebase) callback post-rewrite rebase;;
        merge) callback post-merge 0;;
    esac
fi
exit "$result"
